import{z as B,x as i,o as t,c as d,q as o,j as l,D as s,d as e,s as A,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Gustafson 定律","description":"","frontmatter":{"title":"Gustafson 定律","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gustafson-law.md","filePath":"cs/gustafson-law.md","lastUpdated":1791063341000}'),p={name:"cs/gustafson-law.md"};function m(f,a,u,h,c,C){const n=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="gustafson-定律" tabindex="-1">Gustafson 定律 <a class="header-anchor" href="#gustafson-定律" aria-label="Permalink to &quot;Gustafson 定律&quot;">​</a></h1><div class="epigraph"><p>Amdahl 钉死的是固定工作量下的加速比；Gustafson 说机器变大时工作量也变大，串行段占比可以下降，扩展才有意义。</p><footer>—— 据 Gustafson, Reevaluating Amdahl&#39;s Law, CACM 1988 整理</footer></div><p><a href="/cs/multi-socket-interconnect">上一课</a> 让并行机可以加 socket。<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a> 已经给出固定问题规模的上限。本课不重讲 NUMA 链路。缺口是 <strong>Gustafson：规模可变时的加速比定义</strong>，避免「永远 5% 串行所以 20 核封顶」被误用到弱扩展场景。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Amdahl：工作量 \\(W\\) 固定，\\(s\\) 为串行比例，加速比 \\(\\le 1/(s+(1-s)/n)\\)。科学计算常在核数增加时把网格加密：并行段涨，串行初始化几乎不变。缺口不是新的 NoC，而是<strong>换分子：把 \\(n\\) 核上跑得动的更大问题当作「同等时间」，定义加速比。</strong></p><p><span class="marginnote">数字实例：取 \\(s=5\\%\\)、\\(n=64\\)。Amdahl 公式给 \\(1/(0.05+0.95/64)\\approx14.3\\)，看似六十四核只换来十四倍；Gustafson 口径下 \\(s+n(1-s)=0.05+64\\times0.95\\approx60.9\\)。两个数都对——它们回答的是不同的问题。</span></p><p><span class="marginnote">常见误区：「永远 5% 串行所以约 20 倍封顶」只对固定工作量成立。把这句话拿去否决「加机器跑更大问题」的采购或上云方案，是用强扩展的尺子量弱扩展的事。</span></p><p><span class="marginnote">直觉类比：Amdahl 问的是「同一车货，换更大的卡车能早到多久」；Gustafson 问的是「车队变大后，同样时间内能多运多少货」。货物量固定与否，决定了哪个公式适用。</span></p><p><span class="marginnote">Gustafson 的缩放加速比：\\(s+n(1-s)\\) 形式（记号随文本而异）：串行时间固定、并行工作随 \\(n\\) 线性涨时，效率可以保持。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定时间：允许 \\(W_p(n)\\) 增长。报告时必须声明：问题规模、以及串行段是否真的不随 \\(n\\) 涨（I/O、规约树、一致性热点会涨）。与 <a href="/cs/false-sharing">伪共享</a>、跨 socket 延迟：这些会让「并行段」里长出新的串行/争用，Gustafson 不会自动成立。</p><p>另一种误读：把「更多核跑更大网格」的墙钟几乎不变当成强扩展成功。那是弱扩展。用户若要同一网格更快，必须看 Amdahl 曲线。</p>',12)),(t(),l(r,null,{default:s(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AMD%5B%22Amdahl%EF%BC%9AW%20%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20CAP%5B%22%E6%A0%B8%E6%95%B0%E5%BE%88%E5%BF%AB%E5%B0%81%E9%A1%B6%22%5D%0A%20%20GUS%5B%22Gustafson%EF%BC%9AW%20%E9%9A%8F%20n%20%E6%B6%A8%22%5D%20--%3E%20KEEP%5B%22%E5%9B%BA%E5%AE%9A%E6%97%B6%E9%97%B4%E5%86%85%E5%81%9A%E6%9B%B4%E5%A4%9A%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"下一课强/弱扩展把这两种实验设计说成实验室标准：强扩展 ≈ Amdahl 实验；弱扩展 ≈ Gustafson 精神。SPEC 再下一课会警告：基准往往固定输入，更像 Amdahl。",-1)),(t(),l(r,null,{default:s(()=>[A(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E4%BD%A0%E7%9A%84%E9%9C%80%E6%B1%82%E6%98%AF%EF%BC%9F%22%5D%20--%3E%20Q1%7B%22%E5%90%8C%E4%B8%80%E9%97%AE%E9%A2%98%E8%A6%81%E6%9B%B4%E5%BF%AB%EF%BC%9F%22%7D%0A%20%20Q1%20--%20%22%E6%98%AF%22%20--%3E%20STRONG%5B%22%E7%9C%8B%20Amdahl%20%2F%20%E5%BC%BA%E6%89%A9%E5%B1%95%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20Q1%20--%20%22%E4%B8%8D%EF%BC%8C%E8%A6%81%E6%9B%B4%E5%A4%A7%E9%97%AE%E9%A2%98%E5%90%8C%E6%97%B6%E9%97%B4%22%20--%3E%20Q2%7B%22%E4%B8%B2%E8%A1%8C%E6%AE%B5%E7%9C%9F%E4%B8%8D%E9%9A%8F%20n%20%E6%B6%A8%EF%BC%9F%22%7D%0A%20%20Q2%20--%20%22I%2FO%E3%80%81%E8%A7%84%E7%BA%A6%E4%BC%9A%E6%B6%A8%22%20--%3E%20FIX%5B%22%E4%B8%A4%E6%9D%A1%E5%AE%9A%E5%BE%8B%E9%83%BD%E8%A6%81%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20Q2%20--%20%22%E5%9F%BA%E6%9C%AC%E4%B8%8D%E6%B6%A8%22%20--%3E%20WEAK%5B%22Gustafson%20%2F%20%E5%BC%B1%E6%89%A9%E5%B1%95%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>本栏不把集群作业调度写成定律证明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不修改 Amdahl 的数学，只加规模假设。串行段随日志因子涨（规约）时两条定律都要修正。强/弱扩展术语下一课钉死。</p><p>后课默认：谈加速比先报问题规模是否随机器变。实验怎么画曲线，用强/弱扩展这对词。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Amdahl 固定工作量；Gustafson 允许工作量随核数增长。</li><li>争用与 I/O 会破坏「串行段不变」的假设。</li><li>强扩展与弱扩展是下一课的实验语言。</li><li>出处：Gustafson, <em>CACM</em>, 1988；Amdahl。</li></ul>',6))])}const F=B(p,[["render",m]]);export{D as __pageData,F as default};
